import {createState,stage,proposeSchedule,simulateMonth,decide,validateSave,canContinue,canDefend,ACTIVITIES,PROJECT_PHASES,PROJECT_TITLES,EVENTS,MONTHS,VERSION,abilityScore} from './engine.js';
import {GRANT_TITLES} from './grants.js';
import {ENDINGS} from './stories.js';
import {studentLine} from './dialogue.js';
import {generateKoreanName} from './names.js';
function freshState(seed=Date.now()){const next=createState('',seed,{locale:'ko'});next.creationSeed=seed>>>0;next.name=generateKoreanName(seed,next.gender);return next;}
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(ko,en)=>lang==='ko'?ko:en;
const validLetter=x=>x&&Object.hasOwn(ENDINGS,x.ending)&&typeof x.id==='string'&&x.id.length<=100&&typeof x.name==='string'&&x.name.length<=24&&typeof x.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&Number.isInteger(x.month)&&x.month>=0&&x.month<=96&&['close','reserved','distant'].includes(x.relationship);
let lang='ko',s=freshState(),gallery=[],letter=null,page=0,busy=false,storageOK=true,installPrompt=null,travelConsent=false,fast=false;
try{lang='ko';s=freshState();const raw=localStorage.getItem('pm-save-v3');if(raw){const parsed=JSON.parse(raw);if(validateSave(parsed)){s=parsed;s.locale='ko';}}const g=JSON.parse(localStorage.getItem('pm-letters-v3')||'[]');if(Array.isArray(g))gallery=g.filter(validLetter).slice(0,40);fast=localStorage.getItem('pm-fast')==='true';}catch{storageOK=false;}
let bridge=null,sequence=0;const requests=new Map();
try{bridge=new Worker('./simulation-worker.js',{type:'module'});bridge.onmessage=e=>{const r=requests.get(e.data.id);if(!r)return;requests.delete(e.data.id);clearTimeout(r.timer);e.data.error?r.reject(new Error(e.data.error)):validateSave(e.data.state)?r.resolve(e.data.state):r.reject(new Error('Invalid simulation response'));};bridge.onerror=()=>{for(const r of requests.values()){clearTimeout(r.timer);r.reject(new Error('Simulation worker unavailable'));}requests.clear();bridge.terminate();bridge=null;};}catch{}
function runEngine(type,payload){if(!bridge)return Promise.resolve(type==='month'?simulateMonth(payload.state,payload.plan,payload.options):decide(payload.state,payload.choice));return new Promise((resolve,reject)=>{const id=++sequence;const timer=setTimeout(()=>{requests.delete(id);reject(new Error('Simulation timed out. Please try again.'));bridge?.terminate();bridge=null;},10000);requests.set(id,{resolve,reject,timer});bridge.postMessage({id,type,...payload});});}
const name=()=>s.name==='김하늘'&&lang==='en'?'Haneul Kim':s.name;
const genderName=g=>({male:t('남성','Male'),female:t('여성','Female'),unspecified:t('미지정','Unspecified')}[g]);
const facultyLabel=k=>({research:t('학술활동','Scholarship'),teaching:t('교육','Teaching'),admin:t('학교행정','Administration'),mentoring:t('학생관리','Advising')}[k]);
const activityName=id=>ACTIVITIES[id]?.[lang]?.[0]||id;
const calendarMonth=m=>((Math.min(m,95)+(lang==='ko'?2:8))%12)+1;
const year=m=>Math.floor(Math.min(m,95)/12)+1;
const monthName=m=>lang==='ko'?`${calendarMonth(m)}월`:new Intl.DateTimeFormat('en',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2000,calendarMonth(m)-1,1)));
const calendar=m=>t(`${year(m)}년차 ${monthName(m)}`,`Year ${year(m)} · ${monthName(m)}`);
function semester(m){const n=calendarMonth(m);return n>=3&&n<=6?t('봄학기','Spring semester'):n>=7&&n<=8?t('여름방학','Summer break'):n>=9&&n<=12?t('가을학기','Fall semester'):t('겨울방학','Winter break');}
const isFestival=()=>[4,10].includes(calendarMonth(s.month));
const isBreak=()=>[1,2,7,8].includes(calendarMonth(s.month));
const phase=()=>s.ending?t('지도 종료','Advising complete'):({undergrad:t('학부연구생','Undergraduate researcher'),masters:t('석사과정','Master’s student'),phd:s.route==='integrated'?t('석박사통합과정','Integrated MS / PhD'):t('박사과정','PhD student')}[stage(s)]);
const currency=n=>lang==='ko'?`${Math.round(n*10).toLocaleString('ko-KR')}만원`:`$${Math.round(n*100).toLocaleString('en-US')}`;
const salaryBase=()=>stage(s)==='undergrad'?13:stage(s)==='masters'?22:30;
const estimate=()=>salaryBase()*s.lab.budget.salary/100+s.lab.budget.environment*2+s.lab.budget.performance*2+s.lab.budget.publicity+({abroad_student:18,abroad_together:34,abroad_shared:26}[s.facultyAction]||0);
const view=()=>['lab','journal','letters','design'].includes(location.hash.slice(1))?location.hash.slice(1):'lab';
function save(){try{if(validateSave(s))localStorage.setItem('pm-save-v3',JSON.stringify(s));localStorage.setItem('pm-language',lang);localStorage.setItem('pm-letters-v3',JSON.stringify(gallery));localStorage.setItem('pm-fast',String(fast));storageOK=true;}catch{storageOK=false;}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function archive(){if(!s.ending)return;const id=s.seed+'-'+s.month+'-'+s.ending;if(!gallery.some(x=>x.id===id)){gallery.unshift({id,ending:s.ending,name:s.name,date:new Date().toISOString().slice(0,10),month:s.month,relationship:abilityScore(s,'rapport')>=70?'close':abilityScore(s,'rapport')>=40?'reserved':'distant',career:{...s.career}});gallery=gallery.slice(0,40);save();}}
archive();
function portrait(){return `<svg class="portrait" viewBox="0 0 80 90" role="img" aria-label="${t('학생의 도트 초상화','A pixel portrait of your student')}"><rect width="80" height="90" fill="#e9edf0"/><g shape-rendering="crispEdges"><path d="M14 90V70h9V60h34v10h9v20" fill="${s.month>=48?'#43525a':'#557391'}"/><path d="M30 55h20v14H30z" fill="#e7b894"/><path d="M24 23h32v9h5v25h-7v7H28v-7h-7V32h3z" fill="#f3c9a7"/><path d="M20 24v18h6V29h12v-7h12v7h8v13h5V21h-7v-7H30v5H20z" fill="#34383e"/><path d="M30 40h4v5h-4zm16 0h4v5h-4" fill="#34383e"/><path d="M34 53h12v3H34z" fill="#995d50"/><path d="M23 68h10l7 10 7-10h10v22H23z" fill="#f7f7f4"/><path d="M38 78h4v12h-4z" fill="#d1d9df"/></g></svg>`;}
function facultyBar(k){const n=s.professor[k];return `<div class="stat ${n<20?'danger':''}"><div><span>${facultyLabel(k)}</span><strong>${Math.round(n)}<small> / 100</small></strong></div><div class="track" role="meter" aria-label="${facultyLabel(k)}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(n)}"><span style="width:${n}%"></span></div></div>`;}
function degreeRequirements(){const st=stage(s),c=s.career,remaining=Math.max(0,Math.ceil(((st==='undergrad'?24:st==='masters'?s.mastersReviewAt:96)-s.month)/6));let checks=st==='undergrad'?[[t('연구실 경험','Research experience'),t('진학 면담에서 결정','Decide at the admission meeting'),false]]:st==='masters'?[[t('논문 제출','Manuscripts submitted'),`${c.submissions} / 1`,c.submissions>=1],[t('학술 발표','Conference presentations'),`${c.conferences} / 1`,c.conferences>=1]]:[[t('논문 제출','Manuscripts submitted'),`${c.submissions} / 3`,c.submissions>=3],[t('논문 게재','Published papers'),`${c.papers} / 3`,c.papers>=3],[t('학술 발표','Conference presentations'),`${c.conferences} / 3`,c.conferences>=3],[t('자격시험','Qualifying exam'),c.qual==='passed'?t('통과','Passed'):c.qual==='failed'?t('재응시 준비','Preparing a retake'):t('응시 예정','Upcoming'),c.qual==='passed']];return `<div class="degree-checks"><div class="degree-heading">${t('학위 진행 현황','Degree audit')}<span>${remaining}${t('학기 남음',' semesters left')}</span></div>${checks.map(([label,value,done])=>`<div><span>${label}</span><strong class="${done?'check-done':''}">${done?'✓ ':''}${value}</strong></div>`).join('')}<p class="small-note">${t('게임 속 학위요건입니다. 학생의 능력 수치는 보이지 않습니다.','Fictional degree requirements. Student abilities remain hidden.')}</p></div>`;}
function sidebar(){return `<aside class="student-panel monthly-panel"><div class="panel-title">${t('지도학생','Your advisee')}<span class="record-id">PM–001</span></div><div class="student-id">${portrait()}<div><h2>${esc(name())}</h2><p>${phase()}</p><span>${genderName(s.gender)} · STEM</span></div></div><details class="student-details" ${innerWidth>=900?'open':''}><summary>학위·교수 업무·연구비 상세<span>${['research','teaching','admin','mentoring'].map(k=>`${facultyLabel(k)} ${Math.round(s.professor[k])}`).join(' · ')}</span></summary>${degreeRequirements()}<div class="faculty-overview"><h3>${t('교수 업무 균형','Faculty workload balance')}</h3><div class="core-stats">${['research','teaching','admin','mentoring'].map(facultyBar).join('')}</div><p class="small-note">${t('어느 한 업무가 0이면 지도와 운영을 계속할 수 없습니다.','If any area reaches zero, advising and lab operations must stop.')}</p></div><dl class="student-numbers"><div><dt>${t('연구비 잔액','Research funds')}</dt><dd>${currency(s.lab.funds)}</dd></div><div><dt>${t('인건비 계상률','Stipend allocation')}</dt><dd>${s.lab.budget.salary}%</dd></div><div><dt>${t('수상 / 추천서','Awards / recommendations')}</dt><dd>${s.career.awards} / ${s.career.recommendations}</dd></div></dl></details>${s.sabbatical.active?`<p class="state-note">${t('연구년 중','On sabbatical')} · ${s.sabbatical.mode==='away'?t('해외·원격 지도','Abroad / remote advising'):t('국내 지도 유지','Advising from home')}</p>`:''}${lang==='ko'&&s.gender==='male'&&s.service.status!=='none'?`<p class="state-note">전문연 ${s.service.status==='planning'?'선발 준비 상담 중':s.service.status==='consulted'?'후속 복무 계획 상담 완료':'신청 계획 없음'}</p>`:''}</aside>`;}
function progress(){return `<div class="year-progress" aria-label="${t('8년의 지도기간','Eight-year timeline')}">${Array.from({length:8},(_,i)=>`<div class="year ${s.month>=i*12+12?'done':s.month>=i*12?'current':''}"><span>${i+1}${t('년','')}</span><i></i></div>`).join('')}</div><div class="progress-label"><span>${t('학부 1–2년 → 석사 3–4년 → 박사 5–8년','Undergraduate 1–2 → master’s 3–4 → PhD 5–8')}</span><span>${t('또는 석박사통합 3–8년','Or integrated MS/PhD 3–8')}</span></div>`;}
function project(){const p=s.project,ph=PROJECT_PHASES[p.phase];return `<section class="project-overview"><div class="section-top"><h2>${t('진행 중인 연구','Active research project')}</h2><span>${t('프로젝트','Project')} ${String(p.id).padStart(2,'0')} · ${s.career.completedProjects}${t('개 완료',' completed')}</span></div><h3>${PROJECT_TITLES[p.titleIndex][lang]}</h3><ol class="project-phases">${PROJECT_PHASES.map((x,i)=>`<li class="${i<p.phase?'done':i===p.phase?'current':''}"><span>${i<p.phase?'✓':i+1}</span>${x[lang]}</li>`).join('')}</ol><div class="project-current"><span>${ph[lang]}</span><span>${Math.min(100,Math.round(p.progress/ph.target*100))}% · ${p.conference?t('발표 완료','Presented'):t('발표 준비 중','Presentation pending')}</span></div><div class="project-track"><span style="width:${Math.min(100,p.progress/ph.target*100)}%"></span></div><p class="small-note">${p.phase===5?t('투고 후 심사 중입니다. 논문 쓰기로 수정 의견에 답할 수 있습니다.','Submitted and under review. Writing activities work on revisions.'):t('한 프로젝트를 끝내면 다음 질문으로 넘어갑니다. 발표와 논문 게재는 별도로 기록됩니다.','Finish one project before beginning the next. Presentations and accepted papers are tracked separately.')}</p></section>`;}
function grantPanel(){const g=s.grants;if(!g)return '';const y=Math.floor(s.month/12)+1,remaining=Math.max(0,g.cycleEnd-s.month),last=Math.max(0,y-1),reported=g.reportYears.includes(last),runway=estimate()>0?Math.floor(s.lab.funds/estimate()):0;return `<details class="grant-panel"><summary><strong>연구과제·산학협력단 관리</strong><span>${g.status==='bridge'?'교내 공백지원 중':'개인기초연구 수행 중'} · ${remaining}개월 남음</span></summary><div class="grant-content"><h3>${GRANT_TITLES[g.titleIndex]}</h3><dl><div><dt>과제 구분</dt><dd>${g.status==='bridge'?'교내 한시적 연구 공백지원':'개인기초연구 · 게임 속 모사 과제'}</dd></div><div><dt>이번 연차 배정액</dt><dd>${currency(g.annualAmount)}</dd></div><div><dt>연차보고·실적 등록</dt><dd>${last===0?'첫 연차 수행 중':reported?`${last}년차 제출 완료`:`${last}년차 보고 지연`}</dd></div><div><dt>현 지출계획으로 운영 가능</dt><dd>약 ${runway}개월 · 추가 입금 제외</dd></div></dl><p>겨울에는 연구 실적·집행 내역을 정리합니다. 행정 업무칸을 2개 이상 배정하거나 ‘연차보고서 작성’을 선택하세요. 3년 과제 종료 전에는 후속 계획과 성과가 심사에 반영됩니다.</p><p class="small-note">기관명·지원체계는 한국 연구현장을 참고했습니다. 과제명, 금액, 3년 주기, 접수·심사 규칙은 게임 설정입니다. 실제 공고나 선정결과를 재현하지 않습니다.</p></div></details>`;}
function report(){const r=s.lastReport;if(!r)return '';const outcomes={completed:t('수행','Completed'),rested:t('충분히 쉬었다','Recovered'),talked:t('이야기를 나눴다','Talked together'),missed:t('수행하지 못했다','Could not complete'),failed:t('결과를 얻지 못했다','No result'),presented:t('학술 발표','Presented'),attended:t('청강·교류','Attended'),unprepared:t('발표를 준비하지 못했다','Not ready to present'),success:t('진척','Progress'),progress:t('연구 진척','Research progress'),recovered:t('충분히 쉬었다','Recovered'),not_completed:t('계획을 수행하지 못했다','Could not complete the plan'),inconclusive:t('유의미한 결과를 얻지 못했다','Inconclusive result'),preparing:t('발표 준비가 더 필요했다','Needs further preparation')};return `<details class="month-report"><summary>${t('지난달 수행 보고','Last month’s report')}<span>${r.results.filter(x=>x.performed).length} / 4 ${t('주 수행','weeks carried out')} · ${r.published?t('논문 게재','Paper published'):t('펼쳐서 확인','Open to inspect')}</span></summary><ol>${r.results.map((w,i)=>`<li><span>${i+1}${t('주차',' week')}</span><strong>${esc(activityName(w.proposed))}</strong><em>${outcomes[w.outcome]||(w.performed?t('계획 수행','Carried out'):t('계획 변경·미수행','Changed / not completed'))}</em></li>`).join('')}</ol></details>`;}
const feedbackOptions={listen:[['이야기를 듣는다','Listen first'],['무난하고 조용한 지도','A calm conversation']],praise:[['칭찬한다','Give praise'],['성과에 맞는 칭찬이 힘이 됩니다.','Praise works when it fits the evidence.']],critique:[['구체적으로 지적한다','Give a specific critique'],['실패의 병목을 함께 짚습니다.','Find the bottleneck in an unsuccessful attempt.']],harsh:[['단호하게 압박한다','Apply pressure'],['당장의 순응, 오래 남는 긴장','Short-term compliance, lasting tension']]};
function schedule(){const proposed=proposeSchedule(s),total=Object.values(s.allocation).reduce((a,b)=>a+b,0),enough=estimate()<=s.lab.funds,shared=s.professorGender!=='unspecified'&&s.professorGender===s.gender;return `<section class="schedule monthly-schedule"><div class="section-top"><h2>${t('주별 지도계획','Weekly advising plan')}</h2><span>${t('한 달에 네 주 · 학생의 제안을 수정합니다.','Four weeks per month · discuss and revise the proposal.')}</span></div>${isFestival()?`<div class="festival-notice"><strong>${monthName(s.month)} ${t('셋째 주 학술대회','conference · week 3')}</strong><span>${t('1·2주 준비 → 3주 발표·청강 → 4주 회복','Prepare in weeks 1–2 → present or attend in week 3 → recover in week 4')}</span></div>`:''}<div class="weekly-planner">${s.plan.map((id,i)=>`<div class="week-plan"><div class="week-heading"><strong>${i+1}${t('주차',' week')}</strong><span>${isFestival()&&i===2?t('고정 학술대회','Fixed conference'):t('논의 후 조정','Discuss & adjust')}</span></div><p class="proposal">${t('학생 제안','Student proposes')}<br><strong>${activityName(proposed[i])}</strong></p><label for="week-${i}">${t('합의한 일정','Agreed schedule')}</label><select id="week-${i}" data-week="${i}" ${isFestival()&&i===2?'disabled':''}>${Object.entries(ACTIVITIES).map(([key,a])=>`<option value="${key}" ${id===key?'selected':''}>${a[lang][0]}</option>`).join('')}</select><p class="week-desc">${ACTIVITIES[id][lang][1]}</p></div>`).join('')}</div><div class="meeting-feedback"><div class="section-top"><h3>${t('이번 면담의 연구 피드백','Feedback at this meeting')}</h3><span>${t('지난달의 수행 보고를 바탕으로','Based on last month’s report')}</span></div><div class="feedback-options">${Object.entries(feedbackOptions).map(([id,txt])=>`<label class="feedback-option ${s.feedback===id?'selected':''}"><input type="radio" name="feedback" value="${id}" ${s.feedback===id?'checked':''}><strong>${txt[0][lang==='ko'?0:1]}</strong><span>${txt[1][lang==='ko'?0:1]}</span></label>`).join('')}</div></div><details class="management-controls"><summary>${t('교수 업무·연구실 예산 조정','Adjust faculty workload & lab budget')}<span>${t('예산과 업무 배분은 다음 달에도 유지됩니다.','Allocations carry forward to the next month.')}</span></summary><div class="management-grid"><fieldset><legend>${t('교수의 업무 배분','Faculty workload allocation')}</legend><p>${t('월간 업무칸 8개를 나눕니다.','Divide eight monthly workload units.')}</p>${Object.entries(s.allocation).map(([k,n])=>`<label class="allocation-row"><span>${facultyLabel(k)}</span><input type="number" min="0" max="8" step="1" data-allocation="${k}" value="${n}" aria-label="${facultyLabel(k)} ${t('업무칸','workload units')}"></label>`).join('')}<p id="allocation-total" class="${total!==8?'danger-text':''}">${t('합계','Total')} ${total} / 8</p></fieldset><fieldset><legend>${t('연구비 집행 계획','Research expenditure')}</legend><p>${t('연구비 모델 · 인건비는 학년 첫 달에 조정','Game budget · stipend adjusted in the first academic month')}</p><label class="budget-row"><span>${t('학생인건비 계상률','Stipend allocation rate')}</span><select data-budget="salary" ${s.month%12!==0?'disabled':''}>${Array.from({length:11},(_,i)=>`<option value="${i*10}" ${s.lab.budget.salary===i*10?'selected':''}>${i*10}%</option>`).join('')}</select></label><p id="stipend-amount">${t('학생인건비','Monthly stipend')} ${currency(salaryBase()*s.lab.budget.salary/100)}</p>${[['environment',t('연구환경','Research environment')],['performance',t('연구성과 지원','Research support')],['publicity',t('대외홍보','Public outreach')]].map(([k,label])=>`<label class="budget-row"><span>${label}</span><input type="number" min="0" max="6" step="1" data-budget="${k}" value="${s.lab.budget[k]}" aria-label="${label}"></label>`).join('')}<p id="expense-amount">${t('이번 달 예상 지출','Estimated expenditure')} ${currency(estimate())}</p></fieldset></div><div class="faculty-special"><label for="faculty-action">${t('이번 달 교수의 추가 활동','Additional faculty activity')}</label><select id="faculty-action"><option value="routine" ${s.facultyAction==='routine'?'selected':''}>${t('평소의 학술·교육 활동','Routine scholarship & teaching')}</option><option value="report" ${s.facultyAction==='report'?'selected':''}>연차보고서 작성·산학협력단 정산 준비</option><option value="funding" ${s.facultyAction==='funding'?'selected':''}>${t('후속 과제 준비·소액 협력연구 확보','Apply for additional funding')}</option><option value="recommend" ${s.facultyAction==='recommend'?'selected':''}>${t('추천서 쓰기 · 논문 게재 후 1년에 1회 인정','Write a recommendation · once a year after publication')}</option><option value="support" ${s.facultyAction==='support'?'selected':''}>${t('학생 지원·원격 면담 강화','Extra student support / remote advising')}</option>${isBreak()?`<optgroup label="${t('방학 중 해외학회','Overseas conference during break')}"><option value="abroad_student" ${s.facultyAction==='abroad_student'?'selected':''}>${t('학생만 보내기','Send the student')} · ${currency(18)}</option><option value="abroad_together" ${s.facultyAction==='abroad_together'?'selected':''}>${t('같이 가기 · 방 2개','Travel together · 2 rooms')} · ${currency(34)}</option>${shared?`<option value="abroad_shared" ${s.facultyAction==='abroad_shared'?'selected':''}>${t('같이 가기 · 같은 숙소 방 1개','Travel together · 1 shared room')} · ${currency(26)}</option>`:''}</optgroup>`:''}</select>${isBreak()&&shared?`<label class="consent"><input id="travel-consent" type="checkbox" ${travelConsent?'checked':''}>${t('같은 방을 사용할 경우 학생의 동의를 확인했습니다.','The student agrees to share a room if that option is chosen.')}</label>`:''}</div></details><div class="monthly-confirm"><div><strong>${t('이번 달 예상 지출','Estimated monthly cost')} <span id="confirm-cost">${currency(estimate())}</span></strong><span>${t('일정 수행은 체력·의욕·관계에 따라 달라집니다.','Execution depends on energy, motivation and trust.')}</span></div><button class="primary" data-ui="advance" ${busy||!validateSave(s)||total!==8||!enough?'disabled':''}>${t('일정 확정 · 한 달 진행','Agree & advance one month')} →</button></div><p class="budget-error ${enough?'hidden':''}" id="budget-error">${t('현재 잔액으로 이 계획을 집행할 수 없습니다. 운영비 또는 여행 계획을 조정하세요.','This plan exceeds available funds. Adjust operations or travel.')}</p></section>`;}
function welcome(){return `<section class="welcome"><h2>${t('새로운 학생이 연구실 문을 두드렸습니다.','A new student is at your door.')}</h2><p>${t('한 명의 학생과 8년을 함께합니다. 매달 면담에서 네 주의 계획을 의논하고, 연구실과 교수의 일상도 돌봅니다. 처음부터 학생의 마음을 모두 알 수는 없습니다.','Spend eight years with one student. Each month, discuss four weekly plans, and care for the lab and your own work. You cannot know everything about them from the start.')}</p><form id="start-form"><label for="student-name">${t('학생 이름','Student name')}</label><input id="student-name" name="studentName" data-auto="true" value="${esc(name())}" maxlength="24" required autocomplete="off"><button class="secondary name-draw" type="button" data-ui="name-draw">통계에서 이름 뽑기 ↻</button><p class="small-note">확인된 1995년생 이름 빈도와 2015년 성씨 분포에서 조합합니다. 이름은 직접 고칠 수 있습니다.</p><div class="start-genders"><label>${t('학생 성별','Student gender')}<select name="gender"><option value="random">${t('무작위 · 남성 55% / 여성 45%','Random · 55% male / 45% female')}</option><option value="male">${t('남성','Male')}</option><option value="female">${t('여성','Female')}</option><option value="unspecified">${t('미지정','Unspecified')}</option></select></label><label>${t('교수 성별','Professor gender')}<select name="professorGender"><option value="unspecified">${t('미지정','Unspecified')}</option><option value="male">${t('남성','Male')}</option><option value="female">${t('여성','Female')}</option></select></label></div><button class="primary" type="submit">${t('첫 면담 시작','Begin the first meeting')} →</button></form><p class="small-note">${t('예상 플레이 약 15분 · 96개월 · 능력과 성격은 숨겨진 상태로 성장','Approx. 15 minutes · 96 months · abilities and personality develop out of sight')}</p></section>`;}
const choice=(value,title,body='',disabled=false)=>`<button class="choice" data-ui="decide" data-choice="${value}" ${disabled?'disabled':''}><strong>${title}</strong>${body?`<span>${body}</span>`:''}</button>`;
function pending(){const p=s.pending;if(!p)return '';let heading='',body='',buttons='';
if(p.kind==='event'){const e=EVENTS.find(e=>e.id===p.id);heading=e.title[lang];body=e.body[lang];buttons=e.options.map((o,i)=>choice(i,o.label[lang])).join('');}
if(p.kind==='route'){heading=t('학부 졸업, 진학의 갈림길','Graduation. A choice about graduate school.');body=canContinue(s)?t('두 해 동안 연구실에서 함께했다. 학생은 이제 다음 몇 해의 이야기를 꺼낸다.','You have spent two years together in the lab. Your student begins to talk about the years ahead.'):t('학생은 대학원에 남지 않기로 했다. 다른 길을 선택하는 마음을 먼저 듣는다.','Your student has chosen not to stay. Listen to what they want from a different path.');buttons=choice('masters',t('석사 → 박사','Master’s → PhD'),t('석사과정 후, 박사 진학을 다시 의논합니다.','Revisit the PhD decision after a master’s.'),!canContinue(s))+choice('integrated',t('석박사통합','Integrated MS / PhD'),t('6년의 통합과정으로 연구를 이어갑니다.','Continue into a six-year integrated program.'),!canContinue(s))+choice('graduate',t('학사 졸업으로 마무리','Finish with a bachelor’s degree'));}
if(p.kind==='masters'){const ready=s.career.submissions>=1&&s.career.conferences>=1;heading=t('석사학위, 다음 학기의 계획','A master’s degree. Plans for next semester.');body=t('석사과정에는 논문 제출 1개와 학술 발표 1개가 필요합니다. 학생과 함께 진학·졸업·보완 학기를 의논합니다.','The master’s requires one submission and one presentation. Discuss whether to continue, graduate, or take another semester to complete the work.');buttons=choice('continue',t('박사과정으로 진학','Continue to a PhD'),'',!ready||!canContinue(s))+choice('graduate',t('석사 졸업','Graduate with a master’s'),'',!ready)+(!ready&&!s.mastersExtended?choice('extend',t('한 학기 보완','Extend by one semester')):!ready?choice('graduate',t('학위를 마치지 못하고 과정 정리','Leave without completing the degree')):'');}
if(p.kind==='qual'){heading=t('박사 자격시험','The qualifying examination');body=t('학생은 그동안의 문헌과 연구 질문을 다시 정리했다. 지금 응시할지, 준비 시간을 더 확보할지 결정한다.','Your student has organized the literature and research questions. Decide whether to take the exam now or make room for more preparation.');buttons=choice('exam',t('자격시험에 응시','Take the examination'))+choice('prepare',t('준비 시간을 확보','Make time to prepare'),t('이번 달 공부와 휴식을 중심으로 다시 계획합니다.','Plan this month around study and recovery.'),s.qualPreparations>=2)+choice('graduate',t('과정을 정리하고 다른 길을 의논','Discuss leaving the program'));}
if(p.kind==='sabbatical'){heading=t('교수의 연구년','Your sabbatical year');body=t('5년차를 앞두고 연구년이 시작된다. 자리를 비우더라도 면담과 수업, 행정의 연결을 준비해야 한다.','Your sabbatical begins as year five approaches. Being away still requires a plan for meetings, teaching and administration.');buttons=choice('home',t('국내에서 연구 · 지도 유지','Research at home; keep advising'),t('교수의 연구 시간과 일상 지도를 함께 확보합니다.','Protect research time while keeping the daily connection.'))+choice('away',t('해외 방문연구 · 원격 지도','Visit a lab abroad; advise remotely'),t('원격 면담을 챙기지 않으면 학생과의 거리가 벌어질 수 있습니다.','Keep remote meetings going, or distance may grow.'));}
if(p.kind==='service'||p.kind==='service-review'){heading=t(p.kind==='service'?'전문연구요원 선발 준비 상담':'학위 후 복무 계획 점검','Academic planning');body=p.kind==='service'?t('학생이 박사 진학과 병역 계획을 함께 묻는다. 지정 자연계 대학원 여부, 선발 일정과 자격은 소속 대학과 병무청에서 확인해야 한다. 상담은 자동 선발이나 병역 해결을 뜻하지 않는다.','Discuss academic plans and next steps.'):t('박사학위 이후 연구 현장과 복무 계획을 함께 점검한다. 2023년 이후 편입자의 학위 취득·후속 복무 규정을 확인하며, 연구실 밖의 계획을 준비한다.','Review plans after the doctorate.');buttons=choice('consult',t('소속 대학과 공식 안내를 함께 확인','Review the official guidance together'))+choice('skip',t('현재 병역 계획을 유지','Keep the current plan'));}
if(p.kind==='defense'){heading=t('여덟 번째 학년의 끝, 학위 심사','The end of year eight. The defense.');body=canDefend(s)?t('논문과 발표, 자격시험의 기록이 모였다. 이제 학생은 자기 이름으로 연구실 밖에 나선다. 그리고 다시 몇 해가 지나, 편지 한 통이 도착한다.','Papers, presentations and an examination are complete. Your student steps beyond the lab under their own name. A few years later, a letter arrives.'):t('학위요건을 아직 다 채우지 못했다. 게임의 8년은 끝났지만, 한 사람의 다음 계획은 끝나지 않았다.','The degree requirements are not all complete. The game’s eight years end; a person’s next plan does not.');buttons=choice('defend',t('심사, 그리고 몇 해 후의 편지','The defense, then a letter years later'));}
return `<section id="decision" class="decision"><div class="decision-label">${t('연구실에서 생긴 일','A moment in the lab')}</div><h2>${heading}</h2><p>${body}</p><div class="choices">${buttons}</div>${p.kind.startsWith('service')&&lang==='ko'?'<p class="small-note"><a href="https://www.mma.go.kr/contents.do?mc=mma0000765" target="_blank" rel="noopener">병무청 전문연구요원 복무 안내 ↗</a></p>':''}</section>`;}
function lab(){return `<div class="lab-layout">${sidebar()}<div class="lab-main"><div class="term-heading"><div><p>${phase()} · ${semester(s.month)}</p><h2>${s.ending?t('그 후의 이야기','The story after'):calendar(s.month)}</h2></div><span class="term-count">${s.month} / 96 ${t('개월','months')}</span></div>${progress()}<div class="student-voice"><p>${s.ending?t('한 사람의 다음 이야기가 시작되었다.','Their next story has begun.'):esc(studentLine(s,lang))}</p><span>― ${esc(name())}</span></div>${s.crisis&&!s.ending?`<div class="notice error" role="alert"><strong>${t('다음 면담을 미루지 마세요.','Do not postpone the next conversation.')}</strong><p>${t('학생이 계획을 이어가기 어려워합니다. 휴식과 대화를 확보하지 않으면 다음 달에는 연구실을 떠날 수 있습니다.','Your student is struggling to continue. Without room for rest and conversation, they may leave next month.')}</p></div>`:''}${Object.values(s.professor).some(n=>n<15)&&!s.ending?`<div class="notice warning"><strong>${t('교수의 업무 균형을 회복해야 합니다.','Your faculty workload needs attention.')}</strong><p>${t('업무 배분에서 낮아진 영역에 시간을 배정하세요. 어느 영역이든 0이면 운영이 종료됩니다.','Allocate time to the neglected area. Any area reaching zero ends lab operations.')}</p></div>`:''}${s.ending?`<section class="ending-summary"><span>${ENDINGS[s.ending].type}</span><h2>${ENDINGS[s.ending].title[lang]}</h2><p>${ENDINGS[s.ending].career[lang]}</p><p>${ENDINGS[s.ending].time[lang]}</p><button class="primary" data-ui="read-current">${t('도착한 편지 읽기','Read the letter that arrived')} →</button><button class="secondary" data-ui="new">${t('다시 시작','Start again')}</button></section>`:!s.started?welcome():s.pending?pending():`${project()}${grantPanel()}${report()}${schedule()}`}</div></div>`;}
function journal(){const entries=s.history.filter(x=>['month','event','route','promotion','qual','sabbatical','submission','paper','conference','recommendation','ending','conference-festival','research-travel','annual-grant','grant-report','grant-report-delay','grant-application','grant-selection'].includes(x.kind)).slice(-180).reverse();return `<section class="content-row"><h2>${t('연구실 기록','Lab notebook')}</h2><div><p class="intro-note">${t('계획과 수행은 다를 수 있습니다. 면담·프로젝트·학위의 기록을 함께 봅니다.','Plans and actions can differ. Read the record of meetings, projects and degrees.')}</p>${entries.length?`<ol class="journal-list">${entries.map(h=>{let title='',body='';if(h.kind==='month'){title=(Array.isArray(h.plan)?h.plan:[]).map(activityName).join(' · ');body=t(`네 주 중 ${(Array.isArray(h.results)?h.results:[]).filter(r=>r?.performed).length}주 수행`,`Carried out ${(Array.isArray(h.results)?h.results:[]).filter(r=>r?.performed).length} of four weeks`);}else if(h.kind==='event'){const e=EVENTS.find(e=>e.id===h.id);title=e?.title[lang];body=e?.options[h.choice]?.label[lang];}else if(h.kind==='ending'){title=ENDINGS[h.ending]?.title?.[lang]||'기록';body=ENDINGS[h.ending]?.career?.[lang]||'';}else{title=({route:t('대학원 진학','Graduate admission'),promotion:t('박사과정 진학','Entered the PhD program'),qual:t(h.passed?'자격시험 통과':'자격시험 재응시 준비',h.passed?'Qualifying exam passed':'Preparing an exam retake'),sabbatical:t('교수 연구년 시작','Faculty sabbatical began'),submission:t('논문 제출','Manuscript submitted'),paper:t('논문 게재','Paper accepted'),conference:t('학술 발표','Conference presentation'),recommendation:t('추천서 발송','Recommendation sent'),'conference-festival':t('정기 학술대회','Scheduled conference'),'research-travel':t('해외학회','Overseas conference'),'grant-report':'연차보고서 제출','grant-report-delay':'연차보고 지연','grant-application':'후속 과제 신청','grant-selection':h.awarded?'후속 과제 선정':'후속 과제 미선정·교내 공백지원','annual-grant':t('연구비 연례 지원','Annual research funding')}[h.kind]);if(h.kind==='annual-grant')body=currency(h.amount);if(h.kind==='research-travel')body=t(`숙박 ${h.rooms||1}개 방`,`Lodging: ${h.rooms||1} room(s)`);}return `<li><time>${calendar(Math.max(0,h.month-1))}</time><div><h3>${esc(title)}</h3>${body?`<p>${esc(body)}</p>`:''}</div></li>`;}).join('')}</ol>`:`<div class="empty-state"><h3>${t('아직 첫 장입니다.','The first page is still blank.')}</h3><p>${t('첫 면담 뒤, 함께 보낸 한 달의 기록이 남습니다.','Complete your first month to begin the notebook.')}</p><a class="primary link-button" href="#lab">${t('학생 지도하러 가기','Go to advising')} →</a></div>`}</div></section>`;}
function letters(){return `<section class="content-row"><h2>${t('도착한 편지','Letters received')}</h2><div><p class="intro-note">${t('학부연구생과 석박사, 8년이라는 시간이 흘렀다. 그리고 다시 몇 해가 지났다.','An undergraduate researcher, then a graduate student. Eight years had passed. And then, a few more.')}</p><div class="letter-grid">${Object.entries(ENDINGS).map(([id,e])=>{const entry=gallery.find(x=>x.ending===id);return `<button class="letter-card ${entry?'unlocked':'locked'}" data-ui="read" data-ending="${id}" ${entry?'':'disabled'}><span class="envelope-icon" aria-hidden="true">${entry?'✉':'—'}</span><span class="ending-type">${e.type}</span><strong>${entry?e.title[lang]:t('아직 도착하지 않은 편지','A letter yet to arrive')}</strong><span>${id==='resident_researcher'&&!entry?'아직 알 수 없는 진로':e.career[lang]}</span><small>${entry?esc(entry.name)+' · '+entry.date:t('미발견','Undiscovered')}</small></button>`;}).join('')}</div><p class="small-note">${t('교수 TRUE END · 6가지 NORMAL END · 히든 진로와 휴학·중간 종료','Professor TRUE END · six NORMAL careers · departures and incomplete programs')}</p></div></section>`;}
const source=(label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
function design(){return `<section class="content-row"><h2>${t('시간과 지도 구조','Time & advising')}</h2><div><p>${t('현재 한국어판은 3월–다음 해 2월의 학년입니다. 영어판은 이후 확장합니다. 8년은 96개월, 내부적으로 384개의 주간 활동입니다. 매달 한 번 일정과 피드백을 확정하고 실제 수행은 따로 계산합니다.','The Korean academic year runs March–February; the English year runs September–August. Eight years contain 96 monthly meetings and 384 weekly activities. Agree on a plan and feedback once a month; actual execution is simulated separately.')}</p><div class="pathway"><div>${t('학생의 연구 보고 → 네 주의 일정 제안','Student report → a proposed four-week schedule')}</div><span>↓</span><div>${t('교수 피드백·일정 조정·업무와 예산 배분','Faculty feedback, revised plans, workload and budget')}</div><span>↓</span><div>${t('주별 실제 수행 → 직렬 프로젝트 → 발표·투고·심사','Weekly execution → serial projects → presentation, submission, review')}</div><span>↓</span><div>${t('진급·qual·연구년·이탈 → 박사학위 → 몇 해 후 편지','Progression, qual, sabbatical, departure → doctorate → a letter years later')}</div></div><p>${t('예의범절·체력·정신력·언어·스트레스·사교성·창의성·성실성·라포·신뢰·운은 연속적인 숨은 파라미터입니다. 수치 대신 대사와 수행 결과로 추론합니다. 초기 기질에 반복된 선택의 이력이 더해져 일정과 대사가 달라집니다. 플레이어는 학위요건·프로젝트·연구성과와 교수의 네 업무 상태를 봅니다.','Learning, research, language, sociability, energy, motivation, rapport and personality are hidden. Initial temperament and repeated experiences shape proposals and dialogue. Players see degree requirements, project reports, outcomes, and their four faculty responsibilities.')}</p></div></section><section class="content-row"><h2>${t('연구실 경영','Lab management')}</h2><div><p>${t('4월·10월 셋째 주는 정기 학술대회입니다. 발표 준비와 이후 회복을 주별로 조정할 수 있습니다. 여름·겨울방학에는 연구비로 해외학회를 지원합니다.','The third week of April and October is a fixed conference. Adjust preparation and recovery week by week. During summer and winter breaks, research funds can support an overseas conference.')}</p><p>${t('학생인건비는 계상률에 비례해 지급됩니다. 매년 3월에 조정합니다. 연구환경·연구성과 지원·홍보는 매달 조정합니다. 계상률의 심리 효과와 과제 지원금액은 게임 밸런스입니다.','Stipends scale with their allocation rate. Adjust rates each March in Korean play, or September in English play. Environment, research support and outreach can change monthly. Psychological effects and grant amounts are game balance values.')}</p><p>${t('한국어의 100% 인건비 기준은 제공하신 학교 안내의 2023.03.01 단가(학사 130만·석사 220만·박사 300만원)를 참조했습니다. 운영비와 연구비 입금·심사 규칙은 가상의 게임 모델입니다.','Korean 100% stipend bases use the supplied university’s rates dated March 1, 2023: KRW 1.3m / 2.2m / 3.0m for undergraduate / master’s / doctoral students. English dollar amounts and operational costs are fictional game values.')} ${source(t('학생인건비 통합관리','Student payroll reference'),'https://www.gnu.ac.kr/research/cm/cntnts/cntntsView.do?cntntsId=3988&mi=7451')}</p></div></section><section class="content-row"><h2>${t('통계와 설계 근거','Evidence & design')}</h2><div><p>${t('통계는 현실의 구조를 참고하는 자료이며, 임용 확률이나 게임의 숨은 능력 기준과 동일하지 않습니다.','Statistics inform the setting. They are distinct from hiring probabilities or hidden game ability thresholds.')}</p><dl class="evidence-list"><div><dt>3,937</dt><dd>${t('사용자 제공 국내 기초자연과학 현직 교수 표본. 물리 846·화학 912·생물 1,531·수학 648명입니다. 학위–첫 임용 연도차의 유효한 3,544쌍에서 중앙값 6년, 사분위수 3·9년입니다. 생존자 표본이므로 모든 박사 중 교수 진출률을 계산할 수 없습니다.','The user’s current-faculty roster: physics 846, chemistry 912, biology 1,531, mathematics 648. In 3,544 valid doctorate-to-first-appointment year pairs, the median gap was six years (quartiles: three, nine). A survivor sample cannot estimate the share of all doctorates becoming professors.')} ${source('Professor research career dashboard','https://github.com/Gahyoun/professor-research-career-dashboard')}</dd></div><div><dt>39%</dt><dd>${t('2024년 미국 내 취업·포닥 확정 신규 박사 33,765명 중 포닥 비율입니다. 포닥을 교수 임용과 구분해 졸업 이후의 과정으로 둡니다.','Of 33,765 new U.S. doctorate recipients with definite U.S. work or postdoc commitments in 2024, 39% were postdocs. Postdoctoral training is distinct from a faculty appointment.')} ${source('NCSES · SED 2024, notes §19','https://ncses.nsf.gov/pubs/nsf26315/report/notes')}</dd></div><div><dt>40%</dt><dd>${t('같은 조사에서 비포닥 미국 내 취업 확정자 20,469명 중 기업 부문 약 40%. 학계 약 40%도 교수만을 뜻하지 않습니다.','In the same survey, about 40% of 20,469 recipients with definite non-postdoc U.S. work commitments were going into industry. The roughly 40% academic category is broader than professors.')} ${source('NCSES · postgraduation trends','https://ncses.nsf.gov/pubs/nsf26315/report/postgraduation-trends')}</dd></div><div><dt>80%</dt><dd>${t('미국 박사 출신 교수 표본의 80%가 20.4%의 대학에서 학위를 받았습니다. 임용에는 개인의 성과 외에도 구조와 기회가 작용합니다.','80% of domestically trained faculty in a U.S. study came from 20.4% of universities. Hiring also reflects institutions and opportunities, beyond individual achievement.')} ${source('Wapman et al., Nature (2022)','https://www.nature.com/articles/s41586-022-05222-x')}</dd></div><div><dt>55:45</dt><dd>${t('학생 성별 생성의 게임 설정입니다. 국가·분야 전체의 실제 STEM 성비를 뜻하지 않습니다. 성별은 능력·성과 보너스에 사용하지 않습니다.','The game’s student generation setting, not an empirical ratio for all STEM fields. Gender never adds ability or research bonuses.')}</dd></div></dl><p class="small-note">${t('김박사넷 공개 경험담은 사건 소재로만 참고했습니다. 발생률·인과관계를 추정하지 않습니다. 참고 시스템·통계·설계식·테스트는 GitHub 문서에 기록합니다.','Public community accounts inform fictional event topics, not event rates or causal claims. System references, data scope, formulas and tests are documented on GitHub.')}</p></div></section>`;}
function render(){const v=view(),titles={lab:t('학생 지도','Advisee management'),journal:t('연구 기록','Progress records'),letters:t('편지함','Alumni correspondence'),design:t('게임 설계','Game architecture')};document.documentElement.lang=lang;document.body.dataset.locale=lang;document.title=`Professor Maker — ${titles[v]}`;$('#app').innerHTML=`<a class="skip-link" href="#main">${t('본문 바로가기','Skip to content')}</a><div class="utility-bar"><div class="container"><span>${t('Professor Maker · 네트워크 과학 연구실','Professor Maker · Network Science Lab')}</span><div><a href="./logos.html" target="_blank" class="logo-preview-link">${t('로고 시안','Logo concepts')}</a><button data-ui="guide">${t('플레이 안내','Help')}</button><button data-ui="settings">${t('저장 관리','Save manager')}</button></div></div></div><header class="site-header"><div class="container header-content"><a class="brand" href="#lab"><img src="./assets/lab-mark.svg" class="lab-brand-mark" alt="Professor Maker Network Science Lab"><span class="brand-name">Professor Maker<small>${t('네트워크 과학 연구실 · 경영·육성 시뮬레이션','Network Science Lab · Faculty Services')}</small></span></a><nav class="header-nav" aria-label="${t('주 메뉴','Main navigation')}"><a href="#lab" ${v==='lab'?'aria-current="page"':''}>${t('연구실','My lab')}</a><a href="#journal" ${v==='journal'?'aria-current="page"':''}>${t('기록','Records')}</a><a href="#letters" ${v==='letters'?'aria-current="page"':''}>${t('편지','Alumni')}</a></nav></div></header><nav class="breadcrumb" aria-label="${t('현재 위치','Breadcrumb')}"><div class="container"><span>${t('홈','Home')}</span><span aria-hidden="true">›</span><strong aria-current="page">${titles[v]}</strong><span class="save-status">${storageOK?t('자동 저장 켜짐','Autosave on'):t('저장 불가 · 파일 내보내기 필요','Storage unavailable · export your save')}</span></div></nav><main id="main" class="container" tabindex="-1"><div class="page-title"><h1>${titles[v]}</h1><button class="text-button" data-ui="print">${t('인쇄','Print')}</button></div><nav class="section-nav" aria-label="${t('게임 메뉴','Game navigation')}">${Object.entries(titles).map(([id,title])=>`<a href="#${id}" ${v===id?'aria-current="page"':''}>${title}<span aria-hidden="true">${v===id?'—':'→'}</span></a>`).join('')}</nav>${v==='lab'?lab():v==='journal'?journal():v==='letters'?letters():design()}</main><footer class="site-footer"><div class="container"><div><strong>Professor Maker</strong><p>${t('기획·원작 편지 Gahyoun Gim · 한 명의 학생과 함께하는 8년','Concept & original letters by Gahyoun Gim · one student, eight years')}</p><small>${t('독립 창작 게임 · GNU의 웹 색상·서체·구성을 참고하며 학교 로고는 사용하지 않습니다.','An independent fictional game. Korean presentation draws on GNU colors, typography and layout, with an original research lab logo.')}</small></div><a href="https://github.com/Gahyoun/professor-maker" target="_blank" rel="noopener noreferrer">GitHub ↗</a></div></footer>`;}
function modal(html){const d=$('#modal');d.innerHTML=`<button class="modal-close" data-ui="close" aria-label="${t('닫기','Close')}">×</button>${html}`;if(!d.open)d.showModal();}
function guide(){modal(`<h2>${t('교수님의 첫 면담 안내','Your first advising meeting')}</h2><ol class="guide-list"><li>${t('매달 학생의 네 주 일정을 논의합니다. 학생 제안과 합의한 계획은 실제 수행과 다를 수 있습니다.','Discuss four weekly activities each month. Proposals and agreed plans may differ from what actually happens.')}</li><li>${t('학생의 능력과 성격은 숨겨져 있습니다. 대사·수행보고·연구성과에서 관찰하세요.','Abilities and personality are hidden. Observe dialogue, reports and research outcomes.')}</li><li>${t('지난달 연구 보고에 맞는 칭찬·지적을 선택하세요. 이유 없는 칭찬이나 근거 없는 지적은 역효과를 냅니다.','Match praise and critique to last month’s evidence. Empty praise or unwarranted criticism can backfire.')}</li><li>${t('학술활동·교육·행정·학생관리 중 어느 업무가 0이면 게임이 끝납니다. 업무칸 합계를 8로 배분하세요.','Any faculty responsibility reaching zero ends the game. Allocate eight workload units.')}</li><li>${t('인건비 계상률은 매년 첫 달에 조정합니다. 연구환경·성과·홍보는 매달 조절할 수 있습니다.','Adjust stipend rates in the first month of each academic year. Environment, support and outreach can change monthly.')}</li><li>${t('4월·10월 셋째 주는 학술대회입니다. 앞의 두 주에 준비하고 마지막 주에 쉬는 계획도 가능합니다.','Week three of April and October is a conference. Prepare beforehand and rest afterward.')}</li><li>${t('2년 뒤 진학, 석사학위와 qual, 5년차 교수 연구년이 찾아옵니다. 학생이 힘들다는 신호를 보내면 다음 달까지 방치하지 마세요.','Admission follows two years, then degree reviews, qual and a year-five sabbatical. Do not ignore warning signs until the next month.')}</li><li>${t('박사학위 후 여섯 진로, 까다로운 교수 TRUE END로 갈립니다. 편지는 졸업 이후 시간이 지난 뒤 도착합니다.','After the PhD, six normal careers and a demanding professor TRUE END branch into letters arriving years later.')}</li></ol><div class="help-foot"><p>${t('15분은 목표 플레이타임입니다. 기다리는 타이머 없이 주요 결정에서 멈춥니다.','Fifteen minutes is the target playtime. There are no compulsory waiting timers; play pauses at important choices.')}</p><p>${t('모바일: Safari 공유 → 홈 화면에 추가 / Chrome 메뉴 → 앱 설치. 첫 온라인 방문 후 오프라인 플레이가 가능합니다.','Mobile: Safari Share → Add to Home Screen / Chrome menu → Install app. Play offline after the first online visit.')}</p>${installPrompt?'<button class="primary" data-ui="install">'+t('앱 설치','Install app')+'</button>':''}</div>`);}
function settings(){modal(`<h2>${t('저장 관리','Save manager')}</h2><p>${t('현재 게임과 편지함을 JSON으로 보관하거나 기기 사이에서 옮깁니다. 저장은 이 브라우저에만 남습니다.','Export your game and letters as JSON to keep them or move between devices. Autosaves stay in this browser.')}</p><div class="settings-buttons"><button class="primary" data-ui="export">${t('저장 파일 내보내기','Export save')}</button><button class="secondary" data-ui="import">${t('저장 파일 불러오기','Import save')}</button><input type="file" id="import-file" accept="application/json,.json" hidden><button class="secondary" data-ui="new">${t('새 학생으로 시작','Start with a new student')}</button></div><label class="consent"><input type="checkbox" id="fast-mode" ${fast?'checked':''}>${t('빠른 진행 · 주간 결과 애니메이션 생략','Fast mode · skip weekly transition animation')}</label><p class="small-note">${t('새로 시작해도 발견한 편지는 보관됩니다.','Starting again preserves discovered letters.')}</p>`);}
function openLetter(entry){if(!entry)return;letter=entry;page=0;showLetter();}
function showLetter(){const e=ENDINGS[letter.ending],n=letter.name==='김하늘'&&lang==='en'?'Haneul Kim':letter.name;let body=e.pages[page][lang].replaceAll('{name}',n);if(letter.ending==='unfinished'&&letter.month<96&&page===0)body=t('학위를 마치기 전에, 다음 계획을 다시 의논할 시간이 왔다.\n\n한 사람의 연구는 계획표와 같은 속도로 흐르지 않았다.','Before the degree was complete, it was time to reconsider the next plan.\n\nA person’s research did not move at the speed of a calendar.');modal(`<div class="letter-reader"><div class="letter-meta">${e.type}<span>${e.career[lang]}</span></div><h2>${e.title[lang]}</h2><p class="letter-time">${letter.ending==='unfinished'&&letter.month<96?t('과정 정리 후 · 다음 계획을 의논하는 메일','After leaving · an email about the next plan'):e.time[lang]}</p><div class="letter-paper">${body.split('\n\n').map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('')}</div><div class="letter-pagination"><button class="secondary" data-ui="prev-page" ${page===0?'disabled':''}>← ${t('이전','Back')}</button><span>${page+1} / ${e.pages.length}</span>${page<e.pages.length-1?`<button class="primary" data-ui="next-page">${t('다음','Next')} →</button>`:`<button class="primary" data-ui="finish-letter">${t('편지를 서랍에 넣기','Put the letter in the drawer')}</button>`}</div></div>`);$('#modal').scrollTop=0;}
function newGame(){modal(`<h2>${t('새로운 이야기를 시작할까요?','Begin a new story?')}</h2><p>${t('현재 게임을 새 게임으로 바꿉니다. 발견한 편지는 보관됩니다.','Replace the current run. Discovered letters are kept.')}</p><div class="settings-buttons"><button class="secondary" data-ui="export">${t('먼저 내보내기','Export first')}</button><button class="primary" data-ui="confirm-new">${t('새 게임 시작','Begin new game')}</button></div>`);}
function exportSave(){if(!validateSave(s)){toast(t('업무 배분과 예산을 올바르게 조정한 뒤 내보내 주세요.','Complete a valid allocation and budget before exporting.'));return;}const url=URL.createObjectURL(new Blob([JSON.stringify({format:'professor-maker',version:VERSION,state:s,gallery},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='professor-maker-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('저장 파일을 내보냈습니다.','Save exported.'));}
function updateCosts(){const total=Object.values(s.allocation).reduce((a,b)=>a+b,0),cost=estimate();if($('#allocation-total')){$('#allocation-total').textContent=t('합계 ','Total ')+total+' / 8';$('#allocation-total').classList.toggle('danger-text',total!==8);}if($('#stipend-amount'))$('#stipend-amount').textContent=t('학생인건비 ','Monthly stipend ')+currency(salaryBase()*s.lab.budget.salary/100);if($('#expense-amount'))$('#expense-amount').textContent=t('이번 달 예상 지출 ','Estimated expenditure ')+currency(cost);if($('#confirm-cost'))$('#confirm-cost').textContent=currency(cost);if($('#budget-error'))$('#budget-error').classList.toggle('hidden',cost<=s.lab.funds);const b=$('[data-ui="advance"]');if(b)b.disabled=busy||!validateSave(s)||total!==8||cost>s.lab.funds;}
function errorMessage(error){const m=error.message;return m.includes('salary')||m.includes('Stipend')?t('인건비 계상률은 학년 첫 달에만 변경할 수 있습니다.','Stipend rates can change only in the first academic month.'):m.includes('consent')?t('학생의 숙박 동의를 확인해 주세요.','Confirm the student’s consent for shared accommodation.'):m.includes('gender')||m.includes('room')?t('공동 숙박 조건을 확인해 주세요. 다른 성별 또는 미지정이면 방 2개가 필요합니다.','Check accommodation: different or unspecified genders require two rooms.'):m.includes('fund')||m.includes('Budget')?t('연구비 잔액이 부족합니다. 계획을 조정해 주세요.','Funding is insufficient. Adjust the plan.'):m.includes('workload')||m.includes('eight')?t('교수 업무칸의 합계를 8로 맞춰 주세요.','Faculty workload units must add up to eight.'):m;}
async function advance(){if(busy)return;busy=true;updateCosts();try{const next=await runEngine('month',{state:s,plan:s.plan,options:{feedback:s.feedback,allocation:s.allocation,budget:s.lab.budget,facultyAction:s.facultyAction,proposal:proposeSchedule(s),travelConsent}});if(!fast){$('#transition').hidden=false;const title=$('#transition-label');for(let i=0;i<4;i++){title.textContent=t(`${i+1}주차를 보내는 중…`,`Week ${i+1} is passing…`);await new Promise(r=>setTimeout(r,170));}$('#transition').hidden=true;}s=next;if(!s.pending&&!s.ending){s.plan=proposeSchedule(s);s.feedback='listen';s.facultyAction='routine';}travelConsent=false;archive();save();render();if(s.pending)$('#decision')?.scrollIntoView({behavior:fast?'auto':'smooth',block:'center'});else if(s.ending)openLetter(gallery.find(x=>x.ending===s.ending&&x.name===s.name));else toast(t('또 한 달의 기록이 쌓였습니다.','Another month in the notebook.'));}catch(error){toast(errorMessage(error));}finally{busy=false;$('#transition').hidden=true;updateCosts();}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ui]');if(!b||b.disabled||busy)return;const ui=b.dataset.ui;if(ui==='name-draw'){const field=$('#student-name'),gender=$('select[name=gender]').value;field.value=generateKoreanName(Date.now(),gender==='random'?s.gender:gender);field.dataset.auto='false';return;}if(ui==='advance'){await advance();return;}if(ui==='language'){lang=lang==='ko'?'en':'ko';s.locale=lang;s.plan=proposeSchedule(s);if(!isBreak()&&s.facultyAction.startsWith('abroad'))s.facultyAction='routine';save();render();return;}if(ui==='guide'){guide();return;}if(ui==='settings'){settings();return;}if(ui==='close'){$('#modal').close();return;}if(ui==='print'){window.print();return;}if(ui==='decide'){busy=true;try{const choice=s.pending.kind==='event'?Number(b.dataset.choice):b.dataset.choice;s=await runEngine('decision',{state:s,choice});if(!s.pending&&!s.ending){s.plan=proposeSchedule(s);s.feedback='listen';s.facultyAction='routine';}archive();save();render();if(s.ending)openLetter(gallery.find(x=>x.ending===s.ending&&x.name===s.name));}catch(error){toast(errorMessage(error));}finally{busy=false;updateCosts();}return;}if(ui==='read-current'){openLetter(gallery.find(x=>x.ending===s.ending&&x.name===s.name));return;}if(ui==='read'){openLetter(gallery.find(x=>x.ending===b.dataset.ending));return;}if(ui==='next-page'){page++;showLetter();return;}if(ui==='prev-page'){page--;showLetter();return;}if(ui==='finish-letter'){$('#modal').close();location.hash='letters';return;}if(ui==='new'){newGame();return;}if(ui==='confirm-new'){s=freshState();letter=null;page=0;save();$('#modal').close();location.hash='lab';render();window.scrollTo(0,0);return;}if(ui==='export'){exportSave();return;}if(ui==='import'){$('#import-file').click();return;}if(ui==='install'&&installPrompt){await installPrompt.prompt();installPrompt=null;$('#modal').close();}});
document.addEventListener('submit',e=>{if(e.target.id!=='start-form')return;e.preventDefault();const data=new FormData(e.target);const original=s,seed=original.creationSeed||Date.now();s=createState(String(data.get('studentName')),seed,{gender:data.get('gender')==='random'?undefined:data.get('gender'),professorGender:data.get('professorGender'),locale:lang});if($('#student-name').dataset.auto==='true')s.name=generateKoreanName(seed,s.gender);s.started=true;save();render();toast(t('첫 면담이 시작되었습니다.','Your first meeting begins.'));});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='student-name')el.dataset.auto='false';if(el.dataset.allocation){s.allocation[el.dataset.allocation]=Number(el.value);updateCosts();}if(el.dataset.budget){s.lab.budget[el.dataset.budget]=Number(el.value);updateCosts();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.name==='gender'&&$('#student-name')?.dataset.auto==='true'){const g=el.value==='random'?s.gender:el.value;$('#student-name').value=generateKoreanName(s.creationSeed||s.seed,g);return;}if(el.dataset.week!==undefined){s.plan[Number(el.dataset.week)]=el.value;const p=el.closest('.week-plan');p.querySelector('.week-desc').textContent=ACTIVITIES[el.value][lang][1];save();return;}if(el.name==='feedback'){s.feedback=el.value;$('.feedback-options').querySelectorAll('label').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));save();return;}if(el.dataset.allocation||el.dataset.budget){updateCosts();save();return;}if(el.id==='faculty-action'){s.facultyAction=el.value;updateCosts();save();return;}if(el.id==='travel-consent'){travelConsent=el.checked;return;}if(el.id==='fast-mode'){fast=el.checked;save();return;}if(el.id!=='import-file')return;const file=el.files[0];if(!file)return;if(file.size>1500000){toast(t('저장 파일이 너무 큽니다.','Save file is too large.'));return;}try{const data=JSON.parse(await file.text());if(data.format!=='professor-maker'||data.version!==VERSION||!validateSave(data.state)||!Array.isArray(data.gallery)||data.gallery.length>40||!data.gallery.every(validLetter))throw new Error('Invalid save');modal(`<h2>${t('저장 파일을 불러올까요?','Import this save?')}</h2><p>${esc(data.state.name)} · ${calendar(data.state.month)}<br>${t('현재 게임을 바꾸고 기존 편지는 함께 보관합니다.','Replace the current run and keep existing discovered letters.')}</p><button class="primary" id="confirm-import">${t('불러오기','Import')}</button>`);$('#confirm-import').addEventListener('click',()=>{s=data.state;s.locale='ko';if(!s.pending&&!s.ending)s.plan=proposeSchedule(s);const seen=new Set(gallery.map(x=>x.id));gallery=[...gallery,...data.gallery.filter(x=>!seen.has(x.id))].slice(0,40);archive();save();$('#modal').close();location.hash='lab';render();toast(t('저장 파일을 불러왔습니다.','Save imported.'));});}catch{toast(t('유효한 월간 버전 저장 파일이 아닙니다.','Not a valid monthly-version save.'));}});
matchMedia('(min-width:900px)').addEventListener('change',e=>{const d=$('.student-details');if(d)d.open=e.matches;});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
$('#modal').addEventListener('click',e=>{if(e.target!==$('#modal'))return;const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();});
$('#modal').addEventListener('keydown',e=>{if(!letter||!$('.letter-reader'))return;if(e.key==='ArrowRight'&&page<ENDINGS[letter.ending].pages.length-1){page++;showLetter();}if(e.key==='ArrowLeft'&&page>0){page--;showLetter();}});
render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
